question.answer:
def make_readings():
    return {"north-pier": 14, "kaitaia": 21}


def reading_for(readings, station):
    return readings[station]


def record(readings, station, celsius):
    readings[station] = celsius


def knows(readings, station):
    return station in readings


def report(readings):
    pieces = []
    for station, celsius in readings.items():
        pieces.append(f"{station}={celsius}")
    return " ".join(pieces)

