question.answer:
_MISSING = object()


def read_settings(cfg):
    port = cfg["port"]
    timeout = cfg.get("timeout", 30)
    retries = cfg.setdefault("retries", 3)
    return port, timeout, retries


def config_table(cfg):
    lines = []
    for key, value in cfg.items():
        lines.append(f"{key:<10}{value}")
    return "\n".join(lines)


def must_get(cfg, key):
    try:
        return cfg[key]
    except KeyError as exc:
        raise RuntimeError(f"device config is missing {key!r}") from exc


def lookup(cfg, key):
    value = cfg.get(key, _MISSING)
    if value is _MISSING:
        return "ABSENT"
    if value is None:
        return "NULL"
    return value

