question.answer:
from collections import Counter, defaultdict


def group_faults(records):
    groups = defaultdict(list)
    for subsystem, code in records:
        groups[subsystem].append(code)
    return groups


def tally_codes(records):
    codes = []
    for subsystem, code in records:
        codes.append(code)
    return Counter(codes)


def top_two(counts):
    return counts.most_common(2)


def merge_report(base, extra):
    added = Counter(base)
    added.update(extra)
    replaced = dict(base)
    replaced.update(extra)
    return added, replaced


def probe(groups, counts, key):
    before = (len(groups), len(counts))
    read = (groups[key], counts[key])
    after = (len(groups), len(counts))
    return before, read, after

