question.answer:
def audit(required, granted):
    missing = required - granted
    extra = granted - required
    overlap = required & granted
    covered = required <= granted
    return missing, extra, overlap, covered


def conflicts(a, b):
    return a.isdisjoint(b), a ^ b


def dedupe(tags):
    return list(dict.fromkeys(tags))


def role_table():
    table = {frozenset({"read", "write"}): "editor"}
    try:
        table[["read", "write"]] = "broken"
    except TypeError as exc:
        message = str(exc)
    return table[frozenset({"write", "read"})], message


def empty_set():
    return set(), type({}).__name__

